import type { ReactElement } from 'react';
import { render } from '@testing-library/react';
import type { RenderResult } from '@testing-library/react';
import { Room } from 'livekit-client';
import { RoomContext } from '@/state/RoomContext';
import type { RoomContextValue } from '@/state/RoomContext';
import { initialRoomState } from '@/state/roomReducer';
import { DEFAULT_MAX_ATTACHMENT_BYTES } from '@/shared/types/protocol';

export function createFakeRoomContextValue(overrides: Partial<RoomContextValue> = {}): RoomContextValue {
  const noop = () => {};
  const asyncNoop = async () => {};
  const base: RoomContextValue = {
    state: initialRoomState,
    dispatch: noop,
    sendWs: () => true,
    retryConnection: noop,
    tileDomRegistry: { current: new Map() },
    audioRegistry: { current: new Map() },
    callStageRef: { current: null },
    isCallFullscreen: false,
    toggleCallFullscreen: asyncNoop,
    fullscreenElement: null,
    audioUnlocked: false,
    deafened: false,
    toggleDeafened: noop,
    preferMuted: false,
    micStarting: false,
    setPreferMuted: noop,
    reconnecting: false,
    livekitRoom: new Room(),
    notifyActiveView: noop,
    registerRequestChatView: noop,
    registerOpenCall: noop,
    openCall: noop,
    requestChatView: noop,
    activeCallConversationId: null,
    joinCall: noop,
    leaveCall: asyncNoop,
    startDmCall: noop,
    acceptDmCall: noop,
    declineDmCall: noop,
    cancelDmCall: noop,
    dmCall: null,
    dmStartedAt: null,
    dmStageConversationId: null,
    clearDmStage: noop,
    startSharing: asyncNoop,
    stopSharing: noop,
    changeSource: asyncNoop,
    pauseSharePreview: asyncNoop,
    resumeSharePreview: asyncNoop,
    shareQuality: 'screen1080',
    setShareQuality: noop,
    startCamera: asyncNoop,
    stopCamera: noop,
    activateMic: asyncNoop,
    toggleMicMuted: asyncNoop,
    updateProfile: asyncNoop,
    uploadProfileImage: async () => '',
    removeProfileImage: asyncNoop,
    menuTarget: null,
    openTileMenu: noop,
    closeTileMenu: () => false,
    soundEmojis: [],
    showStats: false,
    setShowStats: noop,
    notifyVolume: 0.65,
    setNotifyVolume: noop,
    notificationsEnabled: false,
    setNotificationsEnabled: noop,
    hideAudioOnlyTiles: false,
    setHideAudioOnlyTiles: noop,
    showTileBanners: true,
    setShowTileBanners: noop,
    compressImagesDefault: true,
    setCompressImagesDefault: noop,
    colorTheme: 'black',
    setColorTheme: noop,
    mirrorCameraPreview: true,
    setMirrorCameraPreview: noop,
    conversations: [],
    activeConversationId: null,
    openConversation: noop,
    openDirect: noop,
    closeConversation: noop,
    servers: [],
    serverMemberRevision: new Map(),
    serverMemberRoleIds: new Map(),
    setServerMemberSnapshot: noop,
    reorderServers: noop,
    messagesByConversation: new Map(),
    hasMoreByConversation: new Map(),
    loadingOlderByConversation: new Set(),
    unreadByConversation: new Map(),
    unreadStartByConversation: new Map(),
    markConversationRead: noop,
    markServerRead: noop,
    typingByConversation: new Map(),
    sendTyping: noop,
    loadOlderMessages: noop,
    loadNewerMessages: noop,
    loadingNewerByConversation: new Set(),
    newerCountByConversation: new Map(),
    windowGenerationByConversation: new Map(),
    allUsers: new Map(),
    onlineUserIds: new Set(),
    presenceByUser: new Map(),
    ownStatus: { status: 'online', effective: 'online', customStatus: null },
    setPresence: async () => {},
    friendUserIds: new Set(),
    kickFromCall: noop,
    moveToCall: noop,
    actionError: null,
    socialRevision: 0,
    clearActionError: noop,
    accessNotice: null,
    clearAccessNotice: noop,
    sendChatMessage: noop,
    sendSticker: noop,
    pendingByConversation: new Map(),
    retryPendingMessage: noop,
    discardPendingMessage: noop,
    queueMessageWithFiles: noop,
    deleteChatMessage: asyncNoop,
    editChatMessage: asyncNoop,
    removeChatAttachment: asyncNoop,
    suppressChatEmbed: asyncNoop,
    deletingMsgIds: new Set(),
    messageActionErrors: new Map(),
    dismissMessageActionError: noop,
    pendingReactions: new Map(),
    reactToChatMessage: noop,
    replyingTo: null,
    setReplyingTo: noop,
    editingMsgId: null,
    setEditingMsgId: noop,
    reactionParticipantsTarget: null,
    openReactionParticipants: noop,
    closeReactionParticipants: noop,
    hasMoreAfterByConversation: new Map(),
    pendingJumpTarget: null,
    clearPendingJumpTarget: noop,
    jumpToMessage: noop,
    searchResults: [],
    searchLoading: false,
    searchError: null,
    clearSearchError: noop,
    searchMessages: noop,
    maxAttachmentBytes: DEFAULT_MAX_ATTACHMENT_BYTES,
  };
  return { ...base, ...overrides };
}

export function renderWithRoom(ui: ReactElement, overrides: Partial<RoomContextValue> = {}): RenderResult {
  return render(<RoomContext.Provider value={createFakeRoomContextValue(overrides)}>{ui}</RoomContext.Provider>);
}
